#include <vector>
#include <algorithm>

class Solution {
public:
    int kIncreasing(std::vector<int>& arr, int k) {
        int n = arr.size();
        int totalOps = 0;

        for (int i = 0; i < k; ++i) {
            std::vector<int> chain;
            for (int j = i; j < n; j += k) {
                chain.push_back(arr[j]);
            }

            std::vector<int> tails;
            for (int x : chain) {
                auto it = std::upper_bound(tails.begin(), tails.end(), x);
                if (it == tails.end()) tails.push_back(x);
                else *it = x;
            }
            totalOps += chain.size() - tails.size();
        }
        return totalOps;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public int kIncreasing(int[] arr, int k) {
        int n = arr.length;
        int totalOps = 0;

        for (int i = 0; i < k; i++) {
            List<Integer> chain = new ArrayList<>();
            for (int j = i; j < n; j += k) {
                chain.add(arr[j]);
            }

            List<Integer> tails = new ArrayList<>();
            for (int x : chain) {
                int idx = Collections.binarySearch(tails, x);
                if (idx >= 0) {
                    while (idx < tails.size() && tails.get(idx) == x) idx++;
                } else {
                    idx = -(idx + 1);
                }

                if (idx == tails.size()) tails.add(x);
                else tails.set(idx, x);
            }
            totalOps += chain.size() - tails.size();
        }
        return totalOps;
    }
}

