var kIncreasing = function(arr, k) {
    const n = arr.length;
    let totalOps = 0;

    for (let i = 0; i < k; i++) {
        const chain = [];
        for (let j = i; j < n; j += k) {
            chain.push(arr[j]);
        }

        const tails = [];
        for (const x of chain) {
            let low = 0, high = tails.length;
            while (low < high) {
                const mid = (low + high) >> 1;
                if (tails[mid] <= x) low = mid + 1;
                else high = mid;
            }
            if (low === tails.length) tails.push(x);
            else tails[low] = x;
        }
        totalOps += chain.length - tails.length;
    }
    return totalOps;
};
